use super::*;
use os_ui::Rect;
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum Kind{Pan,Zoom,Box,Horizontal,Vertical}
#[derive(Debug,Clone)]pub struct Navigation{pub grabbed:bool,pub kind:Kind,pub x:f32,pub y:f32,pub scroll:f32,pub zoom:f32,pub low:f32,pub span:f32,pub selected:Vec<(u16,usize)>}
pub fn rect(app:&App)->Option<Rect>{let row=app.state.playlist.vocal.row?;let g=pl::PGeom::new(&app.state,app.pl_grid()?);Some(view::pitch_rect(&g,row))}
pub fn zoom_x(app:&mut App,factor:f32,x:f32){if let Some(grid)=app.pl_grid(){let s=&mut app.state;let at=(s.playlist_scroll.0+x-grid.x)/s.playlist_bar_w;s.playlist_bar_w=(s.playlist_bar_w*factor).clamp(4.,pl::zoom_limit(s));s.playlist_scroll.0=(at*s.playlist_bar_w-x+grid.x).max(0.);}}
pub fn zoom_y(app:&mut App,factor:f32,y:f32){if let Some(r)=rect(app){let v=&mut app.state.playlist.vocal;let t=((r.bottom()-y)/r.h).clamp(0.,1.);let pitch=v.low+t*v.span;v.span=(v.span/factor).clamp(6.,72.);v.low=(pitch-t*v.span).clamp(0.,128.-v.span);}}
pub fn fit(app:&mut App,selected:bool){
 let Some(grid)=app.pl_grid()else{return};let row=app.state.playlist.vocal.row;let mut lo=128f32;let mut hi=0f32;let mut a=u32::MAX;let mut b=0;
 for (ci,c) in pl::clips(&app.state).iter().enumerate().filter(|(_,c)|Some(c.track)==row){if let Some(d)=doc(&app.state,ci){let chosen:Vec<_>=d.notes.iter().enumerate().filter(|(i,_)|!selected||app.state.playlist.vocal.selected.contains(&(d.channel,*i))).collect();if chosen.is_empty(){continue;}for(_,n)in chosen{lo=lo.min(n.base+n.shift);hi=hi.max(n.base+n.shift);}a=a.min(c.position);b=b.max(c.end());}}
 if b>a{let bar=f32::from(app.state.project.ppq.max(4))*4.;app.state.playlist_bar_w=(grid.w*0.9*bar/(b-a)as f32).clamp(4.,pl::zoom_limit(&app.state));app.state.playlist_scroll.0=(a as f32/bar*app.state.playlist_bar_w-grid.w*0.05).max(0.);let v=&mut app.state.playlist.vocal;v.span=(hi-lo+8.).clamp(12.,72.);v.low=(lo-4.).clamp(0.,128.-v.span);}
 app.invalidate();
}
pub fn begin(app:&mut App,kind:Kind){let v=&app.state.playlist.vocal;let grabbed=rect(app).is_some_and(|r|{if kind==Kind::Vertical{let top=r.y+(128.-v.low-v.span)/128.*r.h;app.mouse.1>=top&&app.mouse.1<=top+(v.span/128.*r.h).max(8.)}else if kind==Kind::Horizontal{let end=pl::clips(&app.state).iter().map(|c|c.end()).max().unwrap_or(0)as f32/(f32::from(app.state.project.ppq.max(4))*4.)*app.state.playlist_bar_w;let width=(r.w-145.).max(30.);let total=end+r.w;let thumb=(r.w/total*width).max(12.);let x=r.x+(app.state.playlist_scroll.0/total*width).clamp(0.,width-thumb);app.mouse.0>=x&&app.mouse.0<=x+thumb}else{false}});app.drag=Some(Drag::VocalNav(Navigation{grabbed,kind,x:app.mouse.0,y:app.mouse.1,scroll:app.state.playlist_scroll.0,zoom:app.state.playlist_bar_w,low:v.low,span:v.span,selected:if app.shift{v.selected.clone()}else{vec![]}}));if kind==Kind::Box&&!app.shift{app.state.playlist.vocal.selected.clear();}if matches!(kind,Kind::Horizontal|Kind::Vertical){drag(app,app.mouse.0,app.mouse.1);}app.invalidate();}
pub fn drag(app:&mut App,x:f32,y:f32){let Some(Drag::VocalNav(n))=app.drag.clone()else{return};let Some(r)=rect(app)else{return};match n.kind{
 Kind::Pan=>{app.state.playlist_scroll.0=(n.scroll+n.x-x).max(0.);app.state.playlist.vocal.low=(n.low+(y-n.y)/r.h*n.span).clamp(0.,128.-n.span);},
 Kind::Zoom=>{app.state.playlist_scroll.0=n.scroll;app.state.playlist_bar_w=n.zoom;app.state.playlist.vocal.low=n.low;app.state.playlist.vocal.span=n.span;zoom_x(app,2f32.powf((x-n.x)/160.),n.x);zoom_y(app,2f32.powf((n.y-y)/160.),n.y);},
 Kind::Horizontal=>{let end=pl::clips(&app.state).iter().map(|c|c.end()).max().unwrap_or(0)as f32/(f32::from(app.state.project.ppq.max(4))*4.)*app.state.playlist_bar_w;if n.grabbed{app.state.playlist_scroll.0=(n.scroll+(x-n.x)/(r.w-145.).max(30.)*(end+r.w)).clamp(0.,end);}else{app.state.playlist_scroll.0=(((x-r.x)/(r.w-145.).max(30.)).clamp(0.,1.)*(end+r.w)-r.w/2.).max(0.);}},
 Kind::Vertical=>app.state.playlist.vocal.low=(if n.grabbed{n.low-(y-n.y)/r.h*128.}else{(1.-(y-r.y)/r.h)*128.-n.span/2.}).clamp(0.,128.-n.span),
 Kind::Box=>{let area=Rect::new(n.x.min(x),n.y.min(y),(x-n.x).abs(),(y-n.y).abs());let g=pl::PGeom::new(&app.state,app.pl_grid().unwrap());let mut selected=n.selected.clone();for(ci,c)in pl::clips(&app.state).iter().enumerate().filter(|(_,c)|Some(c.track)==app.state.playlist.vocal.row){if let Some(d)=doc(&app.state,ci){for(ni,_)in d.notes.iter().enumerate(){if view::note_rect(&app.state,&g,ci,ni).is_some_and(|rr|{let cr=g.clip_rect(c);let visible=Rect::new(cr.x,r.y,cr.w,r.h).intersect(&r);!rr.intersect(&visible).intersect(&area).is_empty()})&&!selected.contains(&(d.channel,ni)){selected.push((d.channel,ni));}}}}app.state.playlist.vocal.selected=selected;app.state.playlist.vocal.marquee=Some(area);},
 }app.invalidate();}
pub fn wheel(app:&mut App,dx:f32,dy:f32,shift:bool,ctrl:bool)->bool{let Some(r)=rect(app)else{return false};let(x,y)=app.mouse;if !matches!(app.top_hit(x,y).map(|h|&h.action),Some(crate::app::Action::Vocal(_))){return false;}if !r.contains(x,y){return false;}if app.drag.is_some(){return true;}if ctrl{if shift{zoom_y(app,1.18f32.powf(dy+dx),y);}else{zoom_x(app,1.18f32.powf(dy+dx),x);}}else if shift{app.state.playlist_scroll.0=(app.state.playlist_scroll.0-(dx+dy)*65.).max(0.);}else{app.state.playlist_scroll.0=(app.state.playlist_scroll.0-dx*65.).max(0.);let v=&mut app.state.playlist.vocal;v.low=(v.low+dy*v.span/12.).clamp(0.,128.-v.span);}app.invalidate();true}
